/* -----------------------------------------------------------------------
 * touch_calibration.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * BJT2 Sound Modulating Toy — Touch Panel Calibration Implementation
 * Author: Tony (Display/UI subsystem)
 *
 * Raw touch ADC counts -> "is a finger there?" (touch_is_pressed), then
 * -> a pixel on the glass (touch_calibrate), then -> a pixel on the
 * screen for the panel's rotation (touch_panel_to_screen).
 * touch_calibration.h explains the mapping in words.
 *
 * No task of its own: tony_ui.c calls it inside TonyTask, on every touch
 * sample (every 40 ms, through touch_filter.c) for touch_is_pressed and
 * once per tap for the other two. No HAL calls, so the host tests
 * (test_ui.c) run it on a PC.
 * ----------------------------------------------------------------------- */

#include "touch_calibration.h"
#include <stddef.h>

/* -----------------------------------------------------------------------
 * touch_is_pressed
 * A resistive panel reports near-zero or near-full-scale ADC values when
 * nothing is touching it (with no finger, tony_ui.c's pull-up holds the
 * sense sheet at 3.3 V, about 4095 counts). We check both axes against
 * the thresholds defined in ui_types.h.
 * ----------------------------------------------------------------------- */
bool touch_is_pressed(uint16_t adc_x, uint16_t adc_y)
{
    bool x_valid = (adc_x >= TOUCH_NO_PRESS_THRESHOLD_LOW) &&
                   (adc_x <= TOUCH_NO_PRESS_THRESHOLD_HIGH);
    bool y_valid = (adc_y >= TOUCH_NO_PRESS_THRESHOLD_LOW) &&
                   (adc_y <= TOUCH_NO_PRESS_THRESHOLD_HIGH);
    return x_valid && y_valid;
}

/* -----------------------------------------------------------------------
 * touch_calibrate
 * Linear interpolation from ADC range to pixel range, in the panel frame
 * (TOUCH_PANEL_W x TOUCH_PANEL_H), whatever way the screen is turned.
 *
 * The clamping step before the multiplication is critical: if adc_x
 * arrives below TOUCH_X_MIN, the subtraction (adc_x - TOUCH_X_MIN)
 * would wrap around to a very large uint16_t value, producing a pixel
 * coordinate in the thousands. Clamping prevents this entirely.
 *
 * Intermediate values are promoted to uint32_t before multiplication
 * to prevent overflow: TOUCH_PANEL_W (320) * ADC_RANGE (3320) = 1,062,400
 * which exceeds uint16_t's maximum of 65,535.
 * ----------------------------------------------------------------------- */
void touch_calibrate(uint16_t adc_x, uint16_t adc_y,
                     uint16_t *out_px, uint16_t *out_py)
{
    if (out_px == NULL || out_py == NULL) {
        return;
    }

    /* --- X axis --- */
    uint16_t clamped_x = adc_x;
    if (clamped_x < TOUCH_X_MIN) { clamped_x = TOUCH_X_MIN; }
    if (clamped_x > TOUCH_X_MAX) { clamped_x = TOUCH_X_MAX; }

    uint32_t px = ((uint32_t)(clamped_x - TOUCH_X_MIN) * TOUCH_PANEL_W)
                  / (TOUCH_X_MAX - TOUCH_X_MIN);

    /* Clamp output to valid pixel range */
    if (px >= TOUCH_PANEL_W) { px = TOUCH_PANEL_W - 1U; }
    *out_px = (uint16_t)px;

    /* --- Y axis --- */
    uint16_t clamped_y = adc_y;
    if (clamped_y < TOUCH_Y_MIN) { clamped_y = TOUCH_Y_MIN; }
    if (clamped_y > TOUCH_Y_MAX) { clamped_y = TOUCH_Y_MAX; }

    uint32_t py = ((uint32_t)(clamped_y - TOUCH_Y_MIN) * TOUCH_PANEL_H)
                  / (TOUCH_Y_MAX - TOUCH_Y_MIN);

    if (py >= TOUCH_PANEL_H) { py = TOUCH_PANEL_H - 1U; }
    *out_py = (uint16_t)py;
}

/* -----------------------------------------------------------------------
 * touch_panel_to_screen
 * Panel pixel -> screen pixel. The panel frame is main's landscape
 * picture with the Y plate read bottom-to-top, so Y is flipped first
 * (xl, yl = the pixel of main's picture), then turned the same way as
 * the ILI9341 (MADCTL) for the given rotation:
 *   VERTICAL_1    (239 - yl, xl)
 *   HORIZONTAL_1  (xl, yl)                 = main
 *   VERTICAL_2    (yl, 319 - xl)           = VERTICAL_1 turned 180 deg
 *   HORIZONTAL_2  (319 - xl, 239 - yl)
 * All four are turns, never mirrors.
 * ----------------------------------------------------------------------- */
bool touch_panel_to_screen(uint8_t rotation, uint16_t cal_x, uint16_t cal_y,
                           uint16_t *out_sx, uint16_t *out_sy)
{
    if (out_sx == NULL || out_sy == NULL) {
        return false;
    }
    if (cal_x > TOUCH_PANEL_W - 1U) { cal_x = TOUCH_PANEL_W - 1U; }
    if (cal_y > TOUCH_PANEL_H - 1U) { cal_y = TOUCH_PANEL_H - 1U; }

    const uint16_t xl = cal_x;                                   /* landscape picture, 0..319 */
    const uint16_t yl = (uint16_t)(TOUCH_PANEL_H - 1U - cal_y);  /* Y plate reads bottom-to-top */
    uint16_t sx, sy;

    switch (rotation) {
        case UI_ROT_VERTICAL_1:
            sx = (uint16_t)(TOUCH_PANEL_H - 1U - yl);
            sy = xl;
            break;
        case UI_ROT_HORIZONTAL_1:
            sx = xl;
            sy = yl;
            break;
        case UI_ROT_VERTICAL_2:
            sx = yl;
            sy = (uint16_t)(TOUCH_PANEL_W - 1U - xl);
            break;
        case UI_ROT_HORIZONTAL_2:
            sx = (uint16_t)(TOUCH_PANEL_W - 1U - xl);
            sy = (uint16_t)(TOUCH_PANEL_H - 1U - yl);
            break;
        default:
            return false;                       /* outputs untouched */
    }
    *out_sx = sx;
    *out_sy = sy;
    return true;
}
